def _default_trust_policy_sec() -> Dict[str, Any]:
    return {
        "allowed_environments": ["local", "local_only", "trusted_local", "interactive", "night_shift", "lan", "internet_strict"],
        "trusted_hosts": ["localhost", "127.0.0.1", "::1", "local_only"],
        "allow_lan": True,
        "allow_internet_strict": False,
    }


def _load_trust_policy_sec() -> Dict[str, Any]:
    cached = _SECURITY_KEEP_STATE.get("trust_policy")
    if isinstance(cached, dict) and cached:
        return cached

    policy = _default_trust_policy_sec()
    for path in _TRUST_POLICY_PATHS:
        if not os.path.exists(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                policy.update(loaded)
                break
        except Exception:
            continue

    _SECURITY_KEEP_STATE["trust_policy"] = policy
    return policy


def _iso_now_sec() -> str:
    return datetime.now(timezone.utc).isoformat()


def _json_safe_sec(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _json_safe_sec(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_json_safe_sec(v) for v in value]
    return str(value)


def _stables_now_ts_sec() -> int:
    return int(datetime.now(timezone.utc).timestamp())


def _get_stables_sessions_sec() -> Dict[str, Dict[str, Any]]:
    sessions = _SECURITY_KEEP_STATE.get("stables_sessions")
    if not isinstance(sessions, dict):
        sessions = {}
        _SECURITY_KEEP_STATE["stables_sessions"] = sessions
    return sessions


def _stables_extract_context_sec(
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    envelope = dict(shunt_envelope or {})
    request = dict(amip_request or envelope.get("amip_payload") or {})
    context_block = dict(context or {})
    header = envelope.get("header") if isinstance(envelope.get("header"), dict) else {}
    payload = request.get("payload") if isinstance(request.get("payload"), dict) else {}
    machine_profile = request.get("machine_profile") if isinstance(request.get("machine_profile"), dict) else {}
    context_tags = [str(tag).strip().lower() for tag in (envelope.get("context_tags") or []) if tag is not None]
    routing_intent = str(request.get("routing_intent") or envelope.get("intent") or context_block.get("routing_intent") or "").strip().lower()
    workflow_lane = str(
        payload.get("workflow_lane")
        or request.get("workflow_lane")
        or context_block.get("workflow_lane")
        or payload.get("protocol")
        or context_block.get("protocol")
        or ""
    ).strip().lower()
    is_vnce = workflow_lane == "vnce" or "vnce" in routing_intent or payload.get("protocol") == ENVOY_PROTOCOL_VNCE
    is_envoy = bool(payload.get("envoy_mode") or context_block.get("envoy_mode") or any(tag in {"envoy", "vnce"} for tag in context_tags))
    applies = bool(context_block.get("stables_enabled") or payload.get("stables_enabled") or is_vnce or is_envoy)
    session_id = str(
        context_block.get("session_id")
        or payload.get("session_id")
        or envelope.get("request_id")
        or request.get("correlation_id")
        or ""
    ).strip()
    device_identity = str(
        context_block.get("device_identity")
        or context_block.get("device_fingerprint")
        or payload.get("device_identity")
        or payload.get("device_fingerprint")
        or machine_profile.get("profile_id")
        or machine_profile.get("ami_id")
        or envelope.get("ami_id")
        or "local_device"
    ).strip() or "local_device"
    envoy_instance_id = str(
        context_block.get("envoy_instance_id")
        or payload.get("envoy_instance_id")
        or payload.get("envoy_id")
        or header.get("shunt_id")
        or envelope.get("shunt_id")
        or "local_envoy"
    ).strip() or "local_envoy"
    presented_token = str(
        context_block.get("stables_token")
        or context_block.get("presented_token")
        or payload.get("stables_token")
        or payload.get("rotation_token")
        or envelope.get("stables_token")
        or ""
    ).strip()
    hard_enforcement = bool(
        context_block.get("stables_required")
        or payload.get("stables_required")
        or payload.get("rotation_required")
    )
    resume_requested = bool(
        context_block.get("resume_requested")
        or payload.get("resume_requested")
        or payload.get("session_resume")
    )
    session_key = "|".join([session_id or "unknown_session", device_identity, envoy_instance_id])
    return {
        "applies": applies,
        "session_id": session_id,
        "device_identity": device_identity,
        "envoy_instance_id": envoy_instance_id,
        "routing_intent": routing_intent,
        "workflow_lane": workflow_lane or ("vnce" if is_vnce else "control"),
        "presented_token": presented_token,
        "hard_enforcement": hard_enforcement,
        "resume_requested": resume_requested,
        "session_key": session_key,
        "context_tags": context_tags,
    }


def _stables_issue_token_sec(record: Dict[str, Any], presented_token: str = "", now_ts: Optional[int] = None) -> str:
    """Advance STABLES into ACTIVE_ROTATION deterministically without generating or modifying secrets."""
    now_ts = int(now_ts or _stables_now_ts_sec())
    record["current_window"] = now_ts // STABLES_ROTATION_WINDOW_SECONDS
    if str(presented_token or "").strip():
        record["current_token"] = str(presented_token).strip()
    else:
        record["current_token"] = str(record.get("current_token") or "")
    record["state"] = "ACTIVE_ROTATION"
    record["rotation_paused"] = False
    record["last_rotated_at"] = _iso_now_sec()
    record["window_expires_at"] = datetime.fromtimestamp(now_ts + STABLES_ROTATION_WINDOW_SECONDS, timezone.utc).isoformat()
    return str(record.get("current_token") or "")

def _stables_metadata_from_record_sec(record: Dict[str, Any], outcome: str = SECURITY_OUTCOME_ALLOW, reason: str = "STABLES:ok") -> Dict[str, Any]:
    state = str(record.get("state", "CLOSED") or "CLOSED")
    return {
        "applied": True,
        "outcome": outcome,
        "reason": reason,
        "session_id": str(record.get("session_id", "")),
        "device_identity": str(record.get("device_identity", "")),
        "envoy_instance_id": str(record.get("envoy_instance_id", "")),
        "hardness_state": state,
        "rotation_window_status": "paused" if record.get("rotation_paused") else ("inactive" if state == "CLOSED" else "active"),
        "last_verified_at": record.get("last_verified_at"),
        "last_rotated_at": record.get("last_rotated_at"),
        "window_expires_at": record.get("window_expires_at"),
        "resume_window_expires_at": record.get("resume_window_expires_at"),
        "challenge_required": outcome == SECURITY_OUTCOME_CHALLENGE,
        "pending_resume": bool(record.get("pending_resume_token")),
    }

def stables_init_session_sec(
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    context_info = _stables_extract_context_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
    if not context_info.get("applies"):
        return {
            "applied": False,
            "outcome": SECURITY_OUTCOME_ALLOW,
            "reason": "STABLES:not-applicable",
            "hardness_state": "CLOSED",
            "rotation_window_status": "inactive",
            "challenge_required": False,
        }

    sessions = _get_stables_sessions_sec()
    session_key = context_info["session_key"]
    record = sessions.get(session_key)
    if not isinstance(record, dict):
        record = {
            "session_id": context_info["session_id"],
            "device_identity": context_info["device_identity"],
            "envoy_instance_id": context_info["envoy_instance_id"],
            "created_at": _iso_now_sec(),
            "created_at_epoch": _stables_now_ts_sec(),
            "state": "INIT",
            "rotation_paused": False,
            "current_token": "",
            "pending_resume_token": None,
            "resume_window_expires_at": None,
            "last_verified_at": None,
        }
        sessions[session_key] = record

    for key in ("session_id", "device_identity", "envoy_instance_id"):
        record[key] = context_info.get(key) or record.get(key)
    record["state"] = "INIT"
    _stables_issue_token_sec(record, presented_token=context_info.get("presented_token", ""))
    return _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:init-active")

def stables_mark_session_drop_sec(
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    context_info = _stables_extract_context_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
    init_result = stables_init_session_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
    if not init_result.get("applied"):
        return init_result
    sessions = _get_stables_sessions_sec()
    record = sessions.get(context_info["session_key"], {})
    record["state"] = "AWAIT_RESUME"
    record["rotation_paused"] = True
    record["pending_resume_token"] = context_info.get("presented_token") or record.get("current_token") or ""
    record["resume_window_expires_at"] = datetime.fromtimestamp(_stables_now_ts_sec() + STABLES_RESUME_WINDOW_SECONDS, timezone.utc).isoformat()
    return _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:await-resume")

def stables_close_session_sec(
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    context_info = _stables_extract_context_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
    if not context_info.get("applies"):
        return {
            "applied": False,
            "outcome": SECURITY_OUTCOME_ALLOW,
            "reason": "STABLES:not-applicable",
            "hardness_state": "CLOSED",
            "rotation_window_status": "inactive",
        }
    sessions = _get_stables_sessions_sec()
    record = sessions.get(context_info["session_key"], {
        "session_id": context_info["session_id"],
        "device_identity": context_info["device_identity"],
        "envoy_instance_id": context_info["envoy_instance_id"],
        "created_at": _iso_now_sec(),
    })
    record["state"] = "CLOSED"
    record["rotation_paused"] = True
    record["current_token"] = None
    record["pending_resume_token"] = None
    record["resume_window_expires_at"] = None
    record["closed_at"] = _iso_now_sec()
    sessions.pop(context_info["session_key"], None)
    return _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:closed")


def stables_validate_session_sec(
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
    metadata_only: bool = False,
) -> Dict[str, Any]:
    context_info = _stables_extract_context_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
    if not context_info.get("applies"):
        return {
            "applied": False,
            "outcome": SECURITY_OUTCOME_ALLOW,
            "reason": "STABLES:not-applicable",
            "hardness_state": "CLOSED",
            "rotation_window_status": "inactive",
            "challenge_required": False,
        }

    sessions = _get_stables_sessions_sec()
    session_key = context_info["session_key"]
    record = sessions.get(session_key)
    if not isinstance(record, dict):
        init_result = stables_init_session_sec(shunt_envelope=shunt_envelope, amip_request=amip_request, context=context)
        record = sessions.get(session_key, {})
        if context_info.get("resume_requested"):
            init_result.update({
                "outcome": SECURITY_OUTCOME_CHALLENGE,
                "reason": "STABLES:resume-needs-existing-session",
                "challenge_required": True,
                "recommended_action": "start_new_session",
            })
            return init_result
        return init_result

    now_ts = _stables_now_ts_sec()
    created_epoch = int(record.get("created_at_epoch", now_ts) or now_ts)
    if now_ts - created_epoch >= STABLES_ABANDON_TIMEOUT_SECONDS and record.get("state") in {"AWAIT_RESUME", "EXPIRED"}:
        record["state"] = "ABANDONED"
        record["rotation_paused"] = True
        record["current_token"] = ""
        record["pending_resume_token"] = None
        record["resume_window_expires_at"] = None
        metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:abandoned-human-verification-required")
        metadata["recommended_action"] = "initiate_new_session_after_human_verification"
        return metadata

    if record.get("state") == "INIT":
        _stables_issue_token_sec(record, presented_token=context_info.get("presented_token", ""), now_ts=now_ts)

    presented_token = context_info.get("presented_token", "")
    if record.get("state") == "AWAIT_RESUME":
        resume_expires_at = record.get("resume_window_expires_at")
        if resume_expires_at:
            try:
                resume_expired = datetime.fromisoformat(str(resume_expires_at)) <= datetime.now(timezone.utc)
            except Exception:
                resume_expired = True
        else:
            resume_expired = True

        if resume_expired:
            record["state"] = "EXPIRED"
            metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:resume-window-expired")
            metadata["recommended_action"] = "reauth_or_start_new_session"
            return metadata

        if not context_info.get("resume_requested"):
            metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:await-resume")
            metadata["recommended_action"] = "resume_or_expire"
            return metadata

        pending_token = str(record.get("pending_resume_token") or "")
        if not presented_token or not pending_token:
            metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:pending-resume-token-required")
            metadata["recommended_action"] = "present_pending_resume_token"
            return metadata
        if presented_token != pending_token:
            metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_QUARANTINE, reason="STABLES:pending-resume-token-mismatch")
            metadata["recommended_action"] = "quarantine_and_review"
            return metadata

        _stables_issue_token_sec(record, presented_token=presented_token, now_ts=now_ts)
        record["pending_resume_token"] = None
        record["resume_window_expires_at"] = None
        record["last_verified_at"] = _iso_now_sec()
        metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:resume-approved")
        metadata["rotation_window_status"] = "active"
        return metadata

    if record.get("state") == "EXPIRED":
        metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:expired")
        metadata["recommended_action"] = "start_new_session"
        return metadata

    if record.get("state") == "ABANDONED":
        metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_CHALLENGE, reason="STABLES:abandoned-human-verification-required")
        metadata["recommended_action"] = "initiate_new_session_after_human_verification"
        return metadata

    if record.get("state") == "CLOSED":
        return _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:closed")

    if presented_token:
        current_token = str(record.get("current_token") or "")
        if current_token and presented_token != current_token:
            metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_QUARANTINE, reason="STABLES:rotation-token-mismatch")
            metadata["recommended_action"] = "quarantine_and_review"
            return metadata
        _stables_issue_token_sec(record, presented_token=presented_token, now_ts=now_ts)
        record["last_verified_at"] = _iso_now_sec()
        return _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:active")

    metadata = _stables_metadata_from_record_sec(record, outcome=SECURITY_OUTCOME_ALLOW, reason="STABLES:metadata-only")
    metadata["metadata_only"] = bool(metadata_only)
    return metadata

def king_sovereignty_check(auth_token):
    """Minimal sovereign gate: returns True if auth is valid."""
    return auth_token == ROYAL_SIGNET


def scout_house_posture_sec(context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Evaluate the current environment trust posture without changing user data."""
    details = dict(context or {})
    environment = str(details.get("environment") or "local_only").strip().lower() or "local_only"
    host = str(details.get("host") or details.get("envoy_host") or "localhost").strip().lower() or "localhost"
    session_id = str(details.get("session_id") or details.get("request_id") or "").strip()
    policy = _load_trust_policy_sec()
    allowed_env = {str(v).strip().lower() for v in (policy.get("allowed_environments") or [])}
    trusted_hosts = {str(v).strip().lower() for v in (policy.get("trusted_hosts") or [])}
    trusted_host = host in trusted_hosts
    trusted_environment = environment in allowed_env
    if environment == "lan" and not bool(policy.get("allow_lan", True)):
        trusted_environment = False
    if environment == "internet_strict" and not bool(policy.get("allow_internet_strict", False)):
        trusted_environment = False
    trusted = bool(trusted_host and trusted_environment)
    posture = {
        "trusted": trusted,
        "environment": environment,
        "host": host,
        "session_id": session_id,
        "authority_layer": "SCOUT_HOUSE",
        "policy_source": "trust-policy",
        "recommended_action": SECURITY_OUTCOME_ALLOW if trusted else SECURITY_OUTCOME_CHALLENGE,
        "evaluated_at": _iso_now_sec(),
    }
    _SECURITY_KEEP_STATE["posture"] = posture
    return posture


def _validate_self_evolve_signature_sec(amip_request: Dict[str, Any]) -> List[str]:
    errors: List[str] = []
    routing_intent = str(amip_request.get("routing_intent", "")).strip().lower()
    if routing_intent != "self.evolve":
        return errors

    payload = amip_request.get("payload") if isinstance(amip_request.get("payload"), dict) else {}
    if not str(payload.get("delta_signature", "")).strip():
        errors.append("missing_self_evolve_delta_signature")
    if not str(payload.get("signed_by", "")).strip():
        errors.append("missing_self_evolve_signer")
    if bool(payload.get("dry_run", True)) is not True:
        errors.append("self_evolve_requires_dry_run")
    return errors


def _validate_contextual_routing_signals_sec(amip_request: Dict[str, Any]) -> List[str]:
    errors: List[str] = []
    payload = amip_request.get("payload") if isinstance(amip_request.get("payload"), dict) else {}
    if not isinstance(payload, dict):
        return errors

    narrative_mode = str(payload.get("narrative_mode") or payload.get("persona") or "").strip().lower()
    resonance_state = str(payload.get("resonance_state") or payload.get("resonance") or "").strip().lower()
    routing_intent = str(amip_request.get("routing_intent", "")).strip().lower()

    if routing_intent.startswith("document."):
        doc_ctx = payload.get("document_context") if isinstance(payload.get("document_context"), dict) else {}
        if doc_ctx and not str(doc_ctx.get("document_id") or "").strip():
            errors.append("document_context_missing_document_id")

    if resonance_state in {"dissonant", "unstable", "red"}:
        errors.append("resonance_state_requires_challenge")

    if narrative_mode in {"unsafe_override", "raw_bypass"}:
        errors.append("narrative_mode_denied")

    return errors


def safe_zeroize_sec(reason: str = "", scope: str = "volatile") -> Dict[str, Any]:
    """Safe zeroize clears volatile in-memory state only. It never deletes files, NBS, profiles, or envelopes."""
    volatile_cache = _SECURITY_KEEP_STATE.get("volatile_cache")
    if not isinstance(volatile_cache, dict):
        volatile_cache = {}
    cleared_keys = sorted(list(volatile_cache.keys()))
    _SECURITY_KEEP_STATE["volatile_cache"] = {}
    _SECURITY_KEEP_STATE["pending_challenges"] = []
    _SECURITY_KEEP_STATE["last_outcome"] = SECURITY_OUTCOME_ZEROIZE_SAFE
    result = {
        "ok": True,
        "action": SECURITY_OUTCOME_ZEROIZE_SAFE,
        "scope": str(scope or "volatile"),
        "cleared_keys": cleared_keys,
        "cleared_count": len(cleared_keys),
        "files_deleted": 0,
        "nbs_deleted": 0,
        "profiles_deleted": 0,
        "reason": str(reason or "volatile-state-cleared"),
        "timestamp": _iso_now_sec(),
    }
    _SECURITY_KEEP_STATE["last_zeroize"] = result
    return result


def security_vault_lifecycle_sec(action: str = "seal", reason: str = "", incident_id: str = "") -> Dict[str, Any]:
    """Safe Gen1 vault lifecycle: seal, unseal, evict (volatile only), and recover."""
    requested_action = str(action or "seal").strip().lower() or "seal"
    before_state = str(_SECURITY_KEEP_STATE.get("vault_state", "sealed"))
    zeroize_result = None

    if requested_action == "seal":
        after_state = "sealed"
    elif requested_action == "unseal":
        after_state = "unsealed"
    elif requested_action == "evict":
        after_state = "evicted"
        zeroize_result = safe_zeroize_sec(reason=reason or "vault-evict", scope="volatile")
    elif requested_action == "recover":
        after_state = "recovered"
        _SECURITY_KEEP_STATE["control_lockdown"] = False
    else:
        return {
            "ok": False,
            "reason": f"unsupported_vault_action:{requested_action}",
            "vault_state": before_state,
        }

    _SECURITY_KEEP_STATE["vault_state"] = after_state
    result = {
        "ok": True,
        "action": requested_action,
        "vault_state_before": before_state,
        "vault_state_after": after_state,
        "reason": str(reason or f"vault:{requested_action}"),
        "incident_id": str(incident_id or ""),
        "timestamp": _iso_now_sec(),
    }
    if zeroize_result is not None:
        result["zeroize"] = zeroize_result
    return result


def security_incident_lifecycle_sec(
    event_type: str = "security.incident",
    actor: str = "security",
    severity: str = "medium",
    reason: str = "",
    outcome: str = SECURITY_OUTCOME_ALLOW,
    envelope: Optional[Dict[str, Any]] = None,
    recommended_action: str = "monitor",
) -> Dict[str, Any]:
    """Record a full non-destructive incident lifecycle for audit, quarantine, lockdown, and recovery flows."""
    final_outcome = str(outcome or SECURITY_OUTCOME_ALLOW).upper()
    incident_id = f"incident-{int(datetime.now(timezone.utc).timestamp() * 1000)}"
    stages = ["DETECT", "AUDIT"]
    if final_outcome == SECURITY_OUTCOME_QUARANTINE:
        stages.append("QUARANTINE")
    elif final_outcome == SECURITY_OUTCOME_LOCKDOWN:
        stages.append("LOCKDOWN")
        _SECURITY_KEEP_STATE["control_lockdown"] = True
    elif final_outcome == SECURITY_OUTCOME_ZEROIZE_SAFE:
        stages.append("ZEROIZE_SAFE")
    else:
        stages.append("RECOVER")

    incident = {
        "incident_id": incident_id,
        "timestamp": _iso_now_sec(),
        "event_type": event_type,
        "actor": actor,
        "severity": str(severity or "medium").lower(),
        "reason": str(reason or final_outcome),
        "recommended_action": str(recommended_action or "monitor"),
        "final_disposition": final_outcome,
        "stages": stages,
        "envelope": _json_safe_sec(envelope or {}),
    }
    history = _SECURITY_KEEP_STATE.setdefault("incident_history", [])
    history.append(incident)
    if len(history) > 200:
        del history[:-200]

    sheriff_audit(event_type, actor, final_outcome, incident["reason"], details=incident)
    return incident


def evaluate_sovereignty_sec(
    auth_token: str = "",
    shunt_envelope: Optional[Dict[str, Any]] = None,
    amip_request: Optional[Dict[str, Any]] = None,
    session_id: str = "",
    environment: str = "local_only",
    host: str = "localhost",
    presented_token: str = "",
) -> Dict[str, Any]:
    """Evaluate identity, environment, session, envelope, and additive STABLES state with non-destructive outcomes."""
    envelope = dict(shunt_envelope or {})
    amip_payload = dict(amip_request or envelope.get("amip_payload") or {})
    resolved_session_id = session_id or envelope.get("request_id") or amip_payload.get("correlation_id") or ""
    posture = scout_house_posture_sec({
        "environment": environment,
        "host": host,
        "session_id": resolved_session_id,
    })
    stables = stables_validate_session_sec(
        shunt_envelope=envelope,
        amip_request=amip_payload,
        context={
            "session_id": resolved_session_id,
            "environment": environment,
            "host": host,
            "presented_token": presented_token,
        },
        metadata_only=True,
    )

    checks: Dict[str, Dict[str, Any]] = {
        "identity": {
            "ok": king_sovereignty_check(auth_token),
            "reason": "KING:sovereignty-check-passed" if king_sovereignty_check(auth_token) else "KING:sovereignty-check-failed",
        },
        "environment": {
            "ok": posture.get("trusted", False),
            "reason": "environment-trusted" if posture.get("trusted", False) else "environment-challenge-required",
        },
        "session": {
            "ok": bool(resolved_session_id),
            "reason": "session-present" if resolved_session_id else "session-missing",
        },
        "envelope": {
            "ok": True,
            "reason": "envelope-not-supplied",
        },
        "stables": {
            "ok": not stables.get("applied") or stables.get("outcome") == SECURITY_OUTCOME_ALLOW,
            "reason": stables.get("reason", "STABLES:not-applicable"),
            "hardness_state": stables.get("hardness_state", "NOT_APPLICABLE"),
            "rotation_window_status": stables.get("rotation_window_status", "not_applicable"),
        },
    }

    if envelope:
        envelope_validation = validate_bucey_shunt_sec(envelope)
        checks["envelope"] = {
            "ok": envelope_validation.get("valid", False),
            "reason": envelope_validation.get("reason", "BUCEY:unknown"),
            "errors": envelope_validation.get("errors", []),
        }
    elif amip_payload:
        amip_validation = validate_amip_payload_sec(amip_payload)
        checks["envelope"] = {
            "ok": amip_validation.get("valid", False),
            "reason": amip_validation.get("reason", "AMIP:unknown"),
            "errors": amip_validation.get("errors", []),
        }

    if not checks["identity"]["ok"]:
        outcome = SECURITY_OUTCOME_LOCKDOWN
        recommended_action = "freeze_control_and_reauth"
    elif stables.get("applied") and stables.get("outcome") == SECURITY_OUTCOME_QUARANTINE:
        outcome = SECURITY_OUTCOME_QUARANTINE
        recommended_action = "isolate_session_and_review"
    elif not checks["envelope"]["ok"]:
        outcome = SECURITY_OUTCOME_QUARANTINE
        recommended_action = "isolate_request_or_file"
    elif stables.get("applied") and stables.get("outcome") == SECURITY_OUTCOME_CHALLENGE:
        outcome = SECURITY_OUTCOME_CHALLENGE
        recommended_action = stables.get("recommended_action", "reauth_or_revalidate")
    elif not checks["environment"]["ok"] or not checks["session"]["ok"]:
        outcome = SECURITY_OUTCOME_CHALLENGE
        recommended_action = "reauth_or_revalidate"
    else:
        outcome = SECURITY_OUTCOME_ALLOW
        recommended_action = "proceed"

    _SECURITY_KEEP_STATE["last_outcome"] = outcome
    if outcome == SECURITY_OUTCOME_LOCKDOWN:
        _SECURITY_KEEP_STATE["control_lockdown"] = True
    elif outcome == SECURITY_OUTCOME_ALLOW:
        _SECURITY_KEEP_STATE["control_lockdown"] = False

    return {
        "ok": outcome == SECURITY_OUTCOME_ALLOW,
        "outcome": outcome,
        "recommended_action": recommended_action,
        "checks": checks,
        "posture": posture,
        "stables": stables,
        "vault_state": _SECURITY_KEEP_STATE.get("vault_state", "sealed"),
        "timestamp": _iso_now_sec(),
    }

# ===========================================================================
# PALADIN GATE (allow / deny decision)
# ===========================================================================
BAD_SIGNATURES = ["drop table", "sudo", "delete", "rm -rf", "force", "hack"]

def paladin_gate(request_text):
    """Returns (allowed: bool, reason: str)."""
    content = str(request_text).lower()
    for sig in BAD_SIGNATURES:
        if sig in content:
            return False, f"PALADIN:DENY:hostile-signature:{sig}"
    return True, "PALADIN:ALLOW:clean"

# ===========================================================================
# SHERIFF AUDIT (structured event record)
# ===========================================================================
def sheriff_audit(event_type, actor, decision, reason, details: Optional[Dict[str, Any]] = None, **extra):
    """Writes a single audit line; returns the event dict with optional structured metadata."""
    event = {
        "ts": _iso_now_sec(),
        "event_type": event_type,
        "actor": actor,
        "decision": decision,
        "reason": reason,
    }
    if isinstance(details, dict) and details:
        event["details"] = _json_safe_sec(details)
    if extra:
        event.update(_json_safe_sec(extra))
    audit_dir = os.path.join(os.path.dirname(__file__), "logs")
    os.makedirs(audit_dir, exist_ok=True)
    audit_path = os.path.join(audit_dir, "security_audit.ndjson")
    with open(audit_path, "a", encoding="utf-8") as f:
        f.write(json.dumps(event, ensure_ascii=False) + "\n")
    return event

# ===========================================================================
# HARNESS PROOF RUN
# ===========================================================================
def run_security_harness_check(auth_token=ROYAL_SIGNET, request_text="harness:proof:run"):
    """
    Runs the security pillar gate sequence for a harness proof test.
    Returns a result dict with keys: status, reason.
    """
    # Step 1 -- sovereignty check
    if not king_sovereignty_check(auth_token):
        sheriff_audit("security.harness.proof", "king", "DENY", "KING:sovereignty-check-failed")
        return {"status": "FAIL", "reason": "KING:sovereignty-check-failed"}

    # Step 2 -- paladin gate
    allowed, reason = paladin_gate(request_text)
    if not allowed:
        sheriff_audit("security.harness.proof", "paladin", "DENY", reason)
        return {"status": "FAIL", "reason": reason}

    # Step 3 -- sheriff audit record for the passing path
    event = sheriff_audit("security.harness.proof", "sheriff", "ALLOW", reason)

    return {"status": "PASS", "reason": reason, "audit": event}


if __name__ == "__main__":
    print("=" * 55)
    print("SARA SECURITY: Gen0 Harness Proof Test")
    print("=" * 55)
    result = run_security_harness_check()
    print(f"  Status : {result['status']}")
    print(f"  Reason : {result['reason']}")
    print("=" * 55)

# =============================================================================
# SECURITY FSM ROUTER  (shunt_header: sara_security_gen1_base)
# evolution anchor: this file is the baseline for all Sara_security shunt expansions
# =============================================================================
# All security operations route through dispatch_security().
# Control is the only caller that should reach this layer.
#
# Flow (internal to security pillar):
#   control → dispatch_security(command, auth_token, **kwargs)
#                └→ king_sovereignty_check
#                    └→ paladin_gate
#                        └→ sheriff_audit
#                            └→ SecurityFSM.handle(command)
#                                └→ registered action
#                                    └→ result back to control
# =============================================================================

import importlib.util as _ilu
import os as _os
import threading as _threading

# --- Load ShuntFSM from Gen1 core ---
def _load_shunt_fsm():
    _here = _os.path.dirname(_os.path.abspath(__file__))
    _candidates = [
        ("sara_coregen1_sec", _os.path.join(_here, "..", "sara_core", "sara_coregen1.py")),
        ("sara_coregn1_sec", _os.path.join(_here, "..", "sara_core", "sara_coregn1.py")),
    ]
    for _module_name, _path in _candidates:
        if not _os.path.exists(_path):
            continue
        _spec = _ilu.spec_from_file_location(_module_name, _path)
        if _spec is None or _spec.loader is None:
            continue
        _mod = _ilu.module_from_spec(_spec)
        _spec.loader.exec_module(_mod)
        return _mod.ShuntFSM
    raise FileNotFoundError("Could not locate Gen1 CORE FSM module. Checked sara_coregen1.py and sara_coregn1.py")

ShuntFSM = _load_shunt_fsm()


# --- Command wrappers ---

def _cmd_gate_check(kwargs):
    """Run the full king→paladin→sheriff sequence on an arbitrary request."""
    token = kwargs.get("auth_token", "")
    text = str(kwargs.get("text", ""))
    if not king_sovereignty_check(token):
        event = sheriff_audit("gate_check", "king", "DENY", "KING:sovereignty-check-failed")
        return {"allowed": False, "reason": "KING:sovereignty-check-failed", "audit": event}
    allowed, reason = paladin_gate(text)
    decision = "ALLOW" if allowed else "DENY"
    event = sheriff_audit("gate_check", "sheriff" if allowed else "paladin", decision, reason)
    return {"allowed": allowed, "reason": reason, "audit": event}


def _cmd_trust_posture(kwargs):
    context = kwargs.get("context") or {}
    if not isinstance(context, dict):
        context = {"environment": kwargs.get("environment", "local_only"), "host": kwargs.get("host", "localhost")}
    context.setdefault("environment", kwargs.get("environment", context.get("environment", "local_only")))
    context.setdefault("host", kwargs.get("host", context.get("host", "localhost")))
    context.setdefault("session_id", kwargs.get("session_id", context.get("session_id", "")))
    return scout_house_posture_sec(context)


def _cmd_evaluate_sovereignty(kwargs):
    result = evaluate_sovereignty_sec(
        auth_token=kwargs.get("auth_token", ""),
        shunt_envelope=kwargs.get("shunt_envelope") or kwargs.get("envelope") or {},
        amip_request=kwargs.get("amip_request") or kwargs.get("payload") or {},
        session_id=str(kwargs.get("session_id", "") or ""),
        environment=str(kwargs.get("environment", "local_only") or "local_only"),
        host=str(kwargs.get("host", "localhost") or "localhost"),
    )
    if result.get("outcome") != SECURITY_OUTCOME_ALLOW:
        incident = security_incident_lifecycle_sec(
            event_type="security.sovereignty",
            actor="king",
            severity="high" if result.get("outcome") == SECURITY_OUTCOME_LOCKDOWN else "medium",
            reason=result.get("recommended_action", "review"),
            outcome=result.get("outcome", SECURITY_OUTCOME_CHALLENGE),
            envelope=kwargs.get("shunt_envelope") or kwargs.get("envelope") or kwargs.get("amip_request") or {},
            recommended_action=result.get("recommended_action", "review"),
        )
        result["incident"] = incident
    return result


