def _sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _find_windows_defender_cli():
    candidates = []
    env_pf = os.environ.get("ProgramFiles", r"C:\Program Files")
    candidates.append(os.path.join(env_pf, "Windows Defender", "MpCmdRun.exe"))
    candidates.extend(glob.glob(r"C:\ProgramData\Microsoft\Windows Defender\Platform\*\MpCmdRun.exe"))
    for p in candidates:
        if os.path.exists(p):
            return p
    return None


def _scan_with_windows_defender(file_path, timeout_sec=45):
    mpcmd = _find_windows_defender_cli()
    if not mpcmd:
        return {"available": False, "status": "not_available", "detail": "MpCmdRun.exe not found"}
    try:
        proc = subprocess.run(
            [mpcmd, "-Scan", "-ScanType", "3", "-File", file_path],
            capture_output=True,
            text=True,
            timeout=max(5, int(timeout_sec)),
            check=False,
        )
        # Defender return codes vary by version, so we inspect output text too.
        out = f"{proc.stdout}\n{proc.stderr}".lower()
        if "found" in out and "threat" in out:
            return {
                "available": True,
                "status": "threat_found",
                "exit_code": proc.returncode,
                "detail": out[-4000:],
            }
        if proc.returncode == 0:
            return {
                "available": True,
                "status": "clean",
                "exit_code": proc.returncode,
                "detail": out[-2000:],
            }
        return {
            "available": True,
            "status": "scan_error",
            "exit_code": proc.returncode,
            "detail": out[-4000:],
        }
    except Exception as e:
        return {"available": True, "status": "scan_exception", "detail": str(e)}


def _quarantine_file(file_path, reason):
    q_dir = os.path.join(os.path.dirname(__file__), "quarantine")
    os.makedirs(q_dir, exist_ok=True)
    base = os.path.basename(file_path)
    stamp = datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    q_path = os.path.join(q_dir, f"q_{stamp}_{base}")
    try:
        shutil.move(file_path, q_path)
        return {"moved": True, "quarantine_path": q_path, "reason": reason}
    except Exception as e:
        return {"moved": False, "quarantine_path": None, "reason": f"{reason};quarantine-move-failed:{e}"}


def _scan_file_policy(file_path, file_ext="", is_envoy=False, max_file_bytes=100 * 1024 * 1024):
    if not file_path or not os.path.exists(file_path):
        return {"allowed": False, "reason": "SEC:DENY:file-missing"}

    try:
        size = os.path.getsize(file_path)
    except Exception:
        return {"allowed": False, "reason": "SEC:DENY:size-read-failed"}

    if size <= 0:
        return {"allowed": False, "reason": "SEC:DENY:file-empty", "size": size}
    if size > int(max_file_bytes):
        return {"allowed": False, "reason": "SEC:DENY:file-too-large", "size": size}

    ext = (file_ext or os.path.splitext(file_path)[1] or "").lower()
    denied_exec_exts = {".exe", ".dll", ".bat", ".cmd", ".ps1", ".js", ".vbs", ".scr", ".com", ".msi"}
    if ext in denied_exec_exts:
        return {"allowed": False, "reason": f"SEC:DENY:blocked-ext:{ext}", "size": size}

    if is_envoy:
        # Envoy is an incoming I/O protocol: keep format strict and explicit.
        envoy_allowed = {
            ".json", ".nbs", ".txt", ".md", ".csv", ".pdf", ".docx", ".xlsx", ".xls",
            ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff", ".webp", ".zip",
            ".mp4", ".mov", ".avi", ".mkv", ".webm",
            ".mp3", ".wav", ".flac", ".ogg", ".m4a", ".aac",
            ".stl", ".obj",
        }
        if ext and ext not in envoy_allowed:
            return {"allowed": False, "reason": f"SEC:DENY:envoy-ext-not-allowed:{ext}", "size": size}

    try:
        with open(file_path, "rb") as f:
            head = f.read(8192)
    except Exception:
        return {"allowed": False, "reason": "SEC:DENY:read-head-failed", "size": size}

    low_head = head.lower()
    bad_markers = [
        b"powershell -", b"cmd.exe", b"<script", b"wscript", b"cscript", b"mshta",
        b"mimikatz", b"invoke-expression", b"downloadstring",
    ]
    for marker in bad_markers:
        if marker in low_head:
            return {"allowed": False, "reason": f"SEC:DENY:signature:{marker.decode('utf-8', errors='ignore')}", "size": size}

    digest = None
    try:
        digest = _sha256_file(file_path)
    except Exception:
        digest = None

    return {
        "allowed": True,
        "reason": "SEC:ALLOW:policy-clean",
        "size": size,
        "sha256": digest,
        "ext": ext,
    }


def _cmd_scan_file(kwargs):
    """Scan a staged file with policy checks and optional Defender scan."""
    file_path = kwargs.get("file_path", "")
    file_ext = kwargs.get("file_ext", "")
    max_file_bytes = kwargs.get("max_file_bytes", 100 * 1024 * 1024)
    run_defender = bool(kwargs.get("use_windows_defender", True))

    policy = _scan_file_policy(
        file_path=file_path,
        file_ext=file_ext,
        is_envoy=False,
        max_file_bytes=max_file_bytes,
    )
    if not policy.get("allowed"):
        q = _quarantine_file(file_path, policy.get("reason", "SEC:DENY:policy"))
        sheriff_audit("security.scan_file", "sheriff", "DENY", q.get("reason", policy.get("reason", "deny")))
        return {
            "allowed": False,
            "reason": q.get("reason", policy.get("reason", "deny")),
            "quarantine": q,
            "policy": policy,
        }

    defender = {"available": False, "status": "disabled", "detail": "disabled by request"}
    if run_defender:
        defender = _scan_with_windows_defender(file_path)
        if defender.get("available") and defender.get("status") == "threat_found":
            q = _quarantine_file(file_path, "SEC:DENY:defender-threat")
            sheriff_audit("security.scan_file", "sheriff", "DENY", "SEC:DENY:defender-threat")
            return {
                "allowed": False,
                "reason": "SEC:DENY:defender-threat",
                "quarantine": q,
                "policy": policy,
                "defender": defender,
            }

    sheriff_audit("security.scan_file", "sheriff", "ALLOW", "SEC:ALLOW:file-clean")
    return {"allowed": True, "reason": "SEC:ALLOW:file-clean", "policy": policy, "defender": defender}


def _validate_vnce_envoy_record(envoy_record: dict) -> dict:
    """
    SECURITY-only VNCE envoy validator. Ensures correct schema, token, caps, and policy.
    """
    if not isinstance(envoy_record, dict):
        raise ValueError("VNCE envoy record must be a dict")

    if envoy_record.get("type") != "envoy":
        raise ValueError("VNCE envoy record must have type='envoy'")

    if envoy_record.get("protocol") != ENVOY_PROTOCOL_VNCE:
        raise ValueError("VNCE envoy record must have protocol='vnce'")

    host = envoy_record.get("host")
    port = envoy_record.get("port")
    token = envoy_record.get("token")

    if not host or not isinstance(host, str):
        raise ValueError("VNCE envoy host is required")

    if not isinstance(port, int) or port <= 0:
        raise ValueError("VNCE envoy port must be a positive integer")

    if not token or not isinstance(token, str):
        raise ValueError("VNCE envoy token is required")

    caps = envoy_record.get("caps") or []
    if "frame" not in caps or "input" not in caps:
        raise ValueError("VNCE envoy caps must include 'frame' and 'input'")

    policy = envoy_record.get("policy")
    if policy is not None and not isinstance(policy, list):
        raise ValueError("VNCE envoy policy must be a list if provided")

    return envoy_record


def _cmd_scan_envoy(kwargs):
    """Envoy intake scan: strict extension policy + optional Defender scan."""
    file_path = kwargs.get("file_path", "")
    file_ext = kwargs.get("file_ext", "")
    max_file_bytes = kwargs.get("max_file_bytes", 100 * 1024 * 1024)
    run_defender = bool(kwargs.get("use_windows_defender", True))

    policy = _scan_file_policy(
        file_path=file_path,
        file_ext=file_ext,
        is_envoy=True,
        max_file_bytes=max_file_bytes,
    )
    if not policy.get("allowed"):
        q = _quarantine_file(file_path, policy.get("reason", "SEC:DENY:envoy-policy"))
        sheriff_audit("security.scan_envoy", "sheriff", "DENY", q.get("reason", policy.get("reason", "deny")))
        return {
            "allowed": False,
            "reason": q.get("reason", policy.get("reason", "deny")),
            "quarantine": q,
            "policy": policy,
        }

    defender = {"available": False, "status": "disabled", "detail": "disabled by request"}
    if run_defender:
        defender = _scan_with_windows_defender(file_path)
        if defender.get("available") and defender.get("status") == "threat_found":
            q = _quarantine_file(file_path, "SEC:DENY:envoy-defender-threat")
            sheriff_audit("security.scan_envoy", "sheriff", "DENY", "SEC:DENY:envoy-defender-threat")
            return {
                "allowed": False,
                "reason": "SEC:DENY:envoy-defender-threat",
                "quarantine": q,
                "policy": policy,
                "defender": defender,
            }

    sheriff_audit("security.scan_envoy", "sheriff", "ALLOW", "SEC:ALLOW:envoy-clean")
    return {"allowed": True, "reason": "SEC:ALLOW:envoy-clean", "policy": policy, "defender": defender}


def _cmd_attest_vnce_session(kwargs: dict) -> dict:
    """
    SECURITY-only attestation for VNCE Envoy sessions.
    Performs sovereignty check, VNCE validation, and audit.
    """
    auth_token = kwargs.get("auth_token", "")
    envoy_record = kwargs.get("envoy_record") or {}

    sovereignty = evaluate_sovereignty_sec(
        auth_token=auth_token,
        session_id=str(envoy_record.get("session_id", "") or ""),
        environment=str(envoy_record.get("environment", "local_only") or "local_only"),
        host=str(envoy_record.get("host", "localhost") or "localhost"),
    )
    if sovereignty.get("outcome") == SECURITY_OUTCOME_LOCKDOWN:
        sheriff_audit("vnce_attest_denied", "king", "LOCKDOWN", "invalid_auth_token", details=sovereignty)
        return {"ok": False, "reason": "invalid_auth_token", "sovereignty": sovereignty}

    try:
        _validate_vnce_envoy_record(envoy_record)
    except Exception as exc:
        sheriff_audit("vnce_attest_denied", "sheriff", "DENY", str(exc), details={"envoy_record": envoy_record})
        return {"ok": False, "reason": str(exc), "sovereignty": sovereignty}

    session_id = str(envoy_record.get("session_id") or "")
    host = str(envoy_record.get("host") or "")
    is_resume_or_reconnect = bool(envoy_record.get("resume_requested") or envoy_record.get("reconnect_requested"))
    if is_resume_or_reconnect:
        last = _SECURITY_KEEP_STATE.setdefault("vnce_last_attested", {}).get(session_id)
        if isinstance(last, dict):
            last_host = str(last.get("host") or "")
            if last_host and host and host != last_host:
                sheriff_audit(
                    "vnce_attest_denied",
                    "sheriff",
                    "QUARANTINE",
                    "vnce_resume_reconnect_host_mismatch",
                    details={"session_id": session_id, "previous_host": last_host, "presented_host": host},
                )
                return {"ok": False, "reason": "vnce_resume_reconnect_host_mismatch", "sovereignty": sovereignty}

    if session_id:
        _SECURITY_KEEP_STATE.setdefault("vnce_last_attested", {})[session_id] = {
            "host": host,
            "attested_at": _iso_now_sec(),
        }

    sheriff_audit(
        "vnce_attest_approved",
        "sheriff",
        "ALLOW",
        "vnce-session-approved",
        details={"host": envoy_record.get("host"), "port": envoy_record.get("port")},
    )
    return {"ok": True, "reason": "approved", "sovereignty": sovereignty}

def _cmd_harness_proof(kwargs):
    """Run the full harness proof sequence."""
    return run_security_harness_check(
        auth_token=kwargs.get("auth_token", ROYAL_SIGNET),
        request_text=kwargs.get("request_text", "harness:proof:run"),
    )


# --- FSM instance for security pillar ---
_SECURITY_FSM_LOCK = _threading.Lock()

_SECURITY_FSM = ShuntFSM(
    states=["ready", "blocked"],
    transitions={
        ("ready",   "gate_check"):    ("ready",   _cmd_gate_check),
        ("ready",   "audit_write"):   ("ready",   _cmd_audit_write),
        ("ready",   "paladin_scan"):  ("ready",   _cmd_paladin_scan),
        ("ready",   SECURITY_CMD_TRUST_POSTURE): ("ready", _cmd_trust_posture),
        ("ready",   SECURITY_CMD_EVALUATE_SOVEREIGNTY): ("ready", _cmd_evaluate_sovereignty),
        ("ready",   SECURITY_CMD_VAULT_LIFECYCLE): ("ready", _cmd_vault_lifecycle),
        ("ready",   SECURITY_CMD_INCIDENT_LIFECYCLE): ("ready", _cmd_incident_lifecycle),
        ("ready",   SECURITY_CMD_SAFE_ZEROIZE): ("ready", _cmd_safe_zeroize),
        ("ready",   STABLES_CMD_INIT_SESSION): ("ready", _cmd_stables_init_session),
        ("ready",   STABLES_CMD_VALIDATE_SESSION): ("ready", _cmd_stables_validate_session),
        ("ready",   STABLES_CMD_MARK_SESSION_DROP): ("ready", _cmd_stables_mark_session_drop),
        ("ready",   STABLES_CMD_RESUME_SESSION): ("ready", _cmd_stables_resume_session),
        ("ready",   STABLES_CMD_CLOSE_SESSION): ("ready", _cmd_stables_close_session),
        ("ready",   "scan_file"):     ("ready",   _cmd_scan_file),
        ("ready",   "scan_envoy"):    ("ready",   _cmd_scan_envoy),
        ("ready",   "validate_amip"): ("ready",   _cmd_validate_amip),
        ("ready",   "validate_bucey_shunt"): ("ready", _cmd_validate_bucey_shunt),
        ("ready",   "validate_mail_transport"): ("ready", _cmd_validate_mail_transport),
        ("ready",   SECURITY_CMD_ATTEST_VNCE_SESSION): ("ready", _cmd_attest_vnce_session),
        ("ready",   "harness_proof"): ("ready",   _cmd_harness_proof),
        ("blocked", "reset"):         ("ready",   None),
    },
    initial_state="ready",
)


def dispatch_security(command: str, auth_token: str = "", **kwargs) -> dict:
    """
    Single entry point for all security pillar operations.
    Intended to be called only by Control (not by external callers directly).

    Args:
        command:    control-routed security command name
        auth_token: must equal ROYAL_SIGNET to pass king check
        **kwargs:   command-specific arguments

    Returns:
        dict with at minimum {"success": bool}.
    """
    with _SECURITY_FSM_LOCK:
        lockdown_exempt = {
            "audit_write",
            SECURITY_CMD_TRUST_POSTURE,
            SECURITY_CMD_EVALUATE_SOVEREIGNTY,
            SECURITY_CMD_VAULT_LIFECYCLE,
            SECURITY_CMD_INCIDENT_LIFECYCLE,
            SECURITY_CMD_SAFE_ZEROIZE,
            "harness_proof",
        }
        if _SECURITY_KEEP_STATE.get("control_lockdown") and command not in lockdown_exempt:
            audit_event = sheriff_audit("dispatch_security", "king", "LOCKDOWN", "KING:control-lockdown-active")
            return {
                "success": False,
                "status": SECURITY_OUTCOME_LOCKDOWN,
                "reason": "KING:control-lockdown-active",
                "security_audit": audit_event,
            }

        # Step 1 — sovereignty check
        if not king_sovereignty_check(auth_token):
            _SECURITY_KEEP_STATE["control_lockdown"] = True
            sheriff_audit("dispatch_security", "king", "DENY", "KING:sovereignty-check-failed")
            if _SECURITY_FSM.state == "ready":
                _SECURITY_FSM.state = "blocked"
            return {"success": False, "status": "DENY", "reason": "KING:sovereignty-check-failed"}

        # Step 2 — paladin gate (scan the command + relevant text payload)
        gate_text = " ".join([
            str(command),
            str(kwargs.get("text", "")),
            str(kwargs.get("request_text", "")),
            str(kwargs.get("reason", "")),
            str(kwargs.get("routing_intent", "")),
        ])
        allowed, reason = paladin_gate(gate_text)
        if not allowed:
            sheriff_audit("dispatch_security", "paladin", "DENY", reason)
            if _SECURITY_FSM.state == "ready":
                _SECURITY_FSM.state = "blocked"
            return {"success": False, "status": "DENY", "reason": reason}

        # Step 3 — audit clean path
        audit_event = sheriff_audit("dispatch_security", "sheriff", "ALLOW", reason)

        # Recover from blocked if needed
        if _SECURITY_FSM.state == "blocked":
            _SECURITY_FSM.handle("reset")

        # Step 4 — FSM dispatch
        fsm_kwargs = dict(kwargs)
        fsm_kwargs["auth_token"] = auth_token
        fsm_kwargs["_dispatch_auth_token"] = auth_token
        fsm_result = _SECURITY_FSM.handle(command, fsm_kwargs)
        if not fsm_result.get("success"):
            return {
                "success": False,
                "error": fsm_result.get("error", "unknown FSM error"),
                "security_audit": audit_event,
            }

        result = fsm_result.get("result")
        if isinstance(result, dict) and result.get("outcome") == SECURITY_OUTCOME_LOCKDOWN:
            _SECURITY_KEEP_STATE["control_lockdown"] = True

        return {
            "success": True,
            "command": command,
            "result": result,
            "fsm_state": _SECURITY_FSM.get_state(),
            "security_audit": audit_event,
        }


def scan_image_con(
    con_image_path: str,
    con_project: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Scan an image file for metadata, size, format anomalies.
    Check for embedded scripts or suspicious EXIF data.

    Args:
        con_image_path : path to image file to scan
        con_project    : optional, writes NBS audit wrapper

    Returns dict with 'success', 'threats' list, 'metadata'.
    Requires: Pillow
    """
    try:
        pil_image = importlib.import_module("PIL.Image")
    except Exception:
        return {"success": False, "error": "Pillow not installed (pip install Pillow)"}

    if not os.path.exists(con_image_path):
        return {"success": False, "error": f"File not found: {con_image_path}"}

    threats = []
    metadata = {}

    try:
        with open(con_image_path, "rb") as f:
            header = f.read(4)
            # Check magic bytes for spoofing
            if header.startswith(b"<?xml") or b"script" in f.read(1000).lower():
                threats.append("Possible embedded script in header")

        img = pil_image.open(con_image_path)
        format_str = str(img.format or "unknown").upper()
        metadata["format"] = format_str
        metadata["width"] = img.width
        metadata["height"] = img.height
        metadata["mode"] = img.mode
        metadata["file_size_kb"] = os.path.getsize(con_image_path) / 1024

        # Check for suspicious EXIF data
        try:
            exif_data = img._getexif()
            if exif_data:
                metadata["has_exif"] = True
                # Check for GPS data that might leak location
                for tag, value in exif_data.items():
                    if tag in (34853, 34854):  # GPS IFD tags
                        threats.append("GPS location data found in EXIF")
                        break
        except Exception:
            pass

        # Check for anomalies
        if metadata["width"] > 10000 or metadata["height"] > 10000:
            threats.append("Extremely large image dimensions (possible DoS vector)")

    except Exception as e:
        return {"success": False, "error": f"scan_image failed: {e}"}

    result: Dict[str, Any] = {
        "success": True,
        "path": con_image_path,
        "threats": threats,
        "metadata": metadata,
        "threat_level": "high" if threats else "low",
    }

    return result


def audit_image_con(
    con_image_path: str,
    con_quarantine_reason: Optional[str] = None,
    con_project: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Audit and optionally quarantine an image based on threats.
    Move to quarantine folder if con_quarantine_reason provided.

    Args:
        con_image_path        : path to image file to audit
        con_quarantine_reason : if provided, move file to quarantine with this reason
        con_project           : optional, writes NBS audit wrapper

    Returns dict with 'success', 'action', 'quarantine_path'.
    Requires: Pillow (for scan), shutil (built-in)
    """
    # First scan the image
    scan_result = scan_image_con(con_image_path, con_project=None)
    if not scan_result.get("success"):
        return scan_result  # Propagate scan error

    threat_level = scan_result.get("threat_level", "low")
    quarantine_path = None
    action = "audited"

    # If high threat or explicit quarantine reason, move to quarantine
    if con_quarantine_reason or threat_level == "high":
        try:
            quarantine_dir = os.path.join(
                os.path.dirname(con_image_path), "__quarantine__"
            )
            os.makedirs(quarantine_dir, exist_ok=True)
            reason_str = (con_quarantine_reason or threat_level).replace(" ", "_")[:50]
            base_name = os.path.basename(con_image_path)
            name, ext = os.path.splitext(base_name)
            quarantine_path = os.path.join(
                quarantine_dir,
                f"{name}__quarantined__{reason_str}{ext}",
            )
            shutil.move(con_image_path, quarantine_path)
            action = "quarantined"
        except Exception as e:
            return {"success": False, "error": f"Quarantine failed: {e}"}

    result: Dict[str, Any] = {
        "success": True,
        "path": con_image_path,
        "action": action,
        "threat_level": threat_level,
        "threats": scan_result.get("threats", []),
        "metadata": scan_result.get("metadata", {}),
    }

    if quarantine_path:
        result["quarantine_path"] = quarantine_path

    return result


def scan_docx_con(
    con_docx_path: str,
) -> Dict[str, Any]:
    """
    Scan a DOCX file for embedded threats: macros, code, OLE objects, external links.

    Args:
        con_docx_path : path to .docx file to scan

    Returns dict with 'success', 'threats' list, 'metadata'.
    Requires: python-docx, zipfile (built-in)
    """
    if not os.path.exists(con_docx_path):
        return {"success": False, "error": f"File not found: {con_docx_path}"}

    threats = []
    metadata = {}

    try:
        import zipfile

        metadata["file_size_kb"] = os.path.getsize(con_docx_path) / 1024
        metadata["format"] = "docx"

        # DOCX is a ZIP file; scan the internal structure
        with zipfile.ZipFile(con_docx_path, "r") as zf:
            file_list = zf.namelist()
            metadata["internal_files"] = len(file_list)

            # Check for VBA macros (usually in /word/vbaProject.bin or /xl/vbaProject.bin)
            if any("vbaProject" in f for f in file_list):
                threats.append("VBA macros detected (potential malware vector)")

            # Check for embedded objects
            if "word/embeddings/" in str(file_list):
                threats.append("Embedded objects found (potential execution vector)")

            # Check external relationships (links to external servers)
            for fname in file_list:
                if fname.endswith(".rels"):
                    try:
                        content = zf.read(fname).decode("utf-8", errors="ignore")
                        if "http://" in content or "ftp://" in content:
                            threats.append(
                                "External link in relationships (potential data exfiltration)"
                            )
                            break
                    except Exception:
                        pass

            # Check document.xml for suspicious fields
            try:
                if "word/document.xml" in file_list:
                    doc_xml = zf.read("word/document.xml").decode("utf-8", errors="ignore")
                    if "<w:fldCode>" in doc_xml or "EXTERNAL" in doc_xml:
                        threats.append("Dynamic field code detected (potential injection)")
                    if "field_update" in doc_xml.lower():
                        threats.append("Auto-update field detected")
            except Exception:
                pass

    except Exception as e:
        return {"success": False, "error": f"scan_docx failed: {e}"}

    result: Dict[str, Any] = {
        "success": True,
        "path": con_docx_path,
        "threats": threats,
        "metadata": metadata,
        "threat_level": "high" if threats else "low",
    }

    return result


def scan_xlsx_con(
    con_xlsx_path: str,
) -> Dict[str, Any]:
    """
    Scan an XLSX file for threats: formulas, external links, VBA, data validation tricks.

    Args:
        con_xlsx_path : path to .xlsx file to scan

    Returns dict with 'success', 'threats' list, 'metadata'.
    Requires: zipfile (built-in)
    """
    import zipfile

    if not os.path.exists(con_xlsx_path):
        return {"success": False, "error": f"File not found: {con_xlsx_path}"}

    threats = []
    metadata = {}

    try:
        metadata["file_size_kb"] = os.path.getsize(con_xlsx_path) / 1024
        metadata["format"] = "xlsx"

        with zipfile.ZipFile(con_xlsx_path, "r") as zf:
            file_list = zf.namelist()
            metadata["internal_files"] = len(file_list)

            # Check for VBA macros
            if any("vbaProject" in f for f in file_list):
                threats.append("VBA macros detected in XLSX")

            # Check workbook.xml for external connections
            try:
                if "xl/workbook.xml" in file_list:
                    wbk = zf.read("xl/workbook.xml").decode("utf-8", errors="ignore")
                    if "externalLink" in wbk:
                        threats.append("External link references found")
                    if "dataConnection" in wbk:
                        threats.append("Data connection found (potential data exfiltration)")
            except Exception:
                pass

            # Check worksheets for suspicious formulas
            for fname in file_list:
                if fname.startswith("xl/worksheets/sheet") and fname.endswith(".xml"):
                    try:
                        sheet_xml = zf.read(fname).decode("utf-8", errors="ignore")
                        # Check for formula injection patterns
                        if "=cmd|" in sheet_xml or "=powershell" in sheet_xml:
                            threats.append("Command injection formula detected")
                        if "=WEBSERVICE(" in sheet_xml:
                            threats.append("WEBSERVICE formula (data exfil potential)")
                        if "=HYPERLINK(" in sheet_xml and ("http" in sheet_xml or "ftp" in sheet_xml):
                            threats.append("Suspicious hyperlink formula")
                    except Exception:
                        pass

            # Check for data validation with malicious patterns
            try:
                if "xl/dataValidations.xml" in file_list:
                    dv = zf.read("xl/dataValidations.xml").decode("utf-8", errors="ignore")
                    if "prompt" in dv.lower() and ("password" in dv.lower() or "login" in dv.lower()):
                        threats.append("Credential prompt data validation (social engineering)")
            except Exception:
                pass

    except Exception as e:
        return {"success": False, "error": f"scan_xlsx failed: {e}"}

    result: Dict[str, Any] = {
        "success": True,
        "path": con_xlsx_path,
        "threats": threats,
        "metadata": metadata,
        "threat_level": "high" if threats else "low",
    }

    return result


def scan_pdf_con(
    con_pdf_path: str,
) -> Dict[str, Any]:
    """
    Scan a PDF file for threats: embedded scripts, form handlers, unusual objects.

    Args:
        con_pdf_path : path to .pdf file to scan

    Returns dict with 'success', 'threats' list, 'metadata'.
    """
    if not os.path.exists(con_pdf_path):
        return {"success": False, "error": f"File not found: {con_pdf_path}"}

    threats = []
    metadata = {}

    try:
        metadata["file_size_kb"] = os.path.getsize(con_pdf_path) / 1024
        metadata["format"] = "pdf"

        # Read raw PDF to look for suspicious patterns
        with open(con_pdf_path, "rb") as f:
            content = f.read()
            metadata["size_bytes"] = len(content)

            # Check for JavaScript in PDF
            if b"/JavaScript" in content or b"/JS" in content:
                threats.append("JavaScript embedded in PDF (potential exploit)")

            # Check for launch actions (external program execution)
            if b"/Launch" in content or b"/SubmitForm" in content:
                threats.append("Launch/form action detected (potential RCE)")

            # Check for embedded files
            if b"/EmbeddedFile" in content:
                threats.append("Embedded files in PDF (potential malware payload)")

            # Check for OpenAction (auto-execute on open)
            if b"/OpenAction" in content:
                threats.append("OpenAction detected (auto-execute on open)")

            # Check for external references
            if b"/XObject" in content or b"/ObjStm" in content:
                if b"http" in content or b"ftp" in content:
                    threats.append("External resource reference in PDF")

            # Check for form field submit to external URL
            if b"/SubmitForm" in content:
                if b"http" in content or b"ftp" in content:
                    threats.append("Form submission to external URL detected")

            # Check for unusually large compressed streams (potential polyglot/exploit)
            if b"stream" in content:
                stream_count = content.count(b"stream")
                metadata["stream_count"] = stream_count
                if stream_count > 50:
                    threats.append("High number of streams (potential polyglot/exploit)")

    except Exception as e:
        return {"success": False, "error": f"scan_pdf failed: {e}"}

    result: Dict[str, Any] = {
        "success": True,
        "path": con_pdf_path,
        "threats": threats,
        "metadata": metadata,
        "threat_level": "high" if threats else "low",
    }

    return result


def audit_files_con(
    con_file_paths: List[str],
    con_quarantine_on_threat: bool = True,
) -> Dict[str, Any]:
    """
    Batch audit multiple office files (DOCX, XLSX, PDF, images).
    Auto-quarantine if threats detected and con_quarantine_on_threat=True.

    Args:
        con_file_paths         : list of file paths to audit
        con_quarantine_on_threat: if True, quarantine threatened files

    Returns dict with 'success', 'results' list, 'quarantined_count'.
    """
    results = []
    quarantined_count = 0

    for fpath in (con_file_paths or []):
        if not os.path.exists(fpath):
            results.append({"path": fpath, "success": False, "error": "File not found"})
            continue

        ext = os.path.splitext(fpath)[1].lower()
        scan_result = None

        if ext == ".docx":
            scan_result = scan_docx_con(fpath)
        elif ext == ".xlsx":
            scan_result = scan_xlsx_con(fpath)
        elif ext == ".pdf":
            scan_result = scan_pdf_con(fpath)
        elif ext in (".png", ".jpg", ".jpeg", ".gif", ".bmp"):
            scan_result = scan_image_con(fpath)
        else:
            results.append({"path": fpath, "success": False, "error": f"Unsupported format: {ext}"})
            continue

        if not scan_result.get("success"):
            results.append(scan_result)
            continue

        threat_level = scan_result.get("threat_level", "low")
        threats = scan_result.get("threats", [])

        action = "passed"
        quarantine_path = None

        if (threat_level == "high" or threats) and con_quarantine_on_threat:
            try:
                quarantine_dir = os.path.join(os.path.dirname(fpath), "__quarantine__")
                os.makedirs(quarantine_dir, exist_ok=True)
                threat_str = (threats[0] if threats else "high_threat").replace(" ", "_")[:40]
                base_name = os.path.basename(fpath)
                name, ext_part = os.path.splitext(base_name)
                quarantine_path = os.path.join(
                    quarantine_dir, f"{name}__quarantined__{threat_str}{ext_part}"
                )
                shutil.move(fpath, quarantine_path)
                action = "quarantined"
                quarantined_count += 1
            except Exception as e:
                results.append(
                    {"path": fpath, "success": False, "error": f"Quarantine failed: {e}"}
                )
                continue

        result_entry = {
            "path": fpath,
            "success": True,
            "threat_level": threat_level,
            "threats": threats,
            "action": action,
        }
        if quarantine_path:
            result_entry["quarantine_path"] = quarantine_path

        results.append(result_entry)

    return {
        "success": True,
        "results": results,
        "quarantined_count": quarantined_count,
        "total_audited": len(con_file_paths or []),
    }


